'use strict';
// Read the exact little-endian PCM fixture generated by the independent Python harness.
const fs = require('node:fs');
const { analyzePcm } = require('../utils/phonetic/analysis');
(async () => {
  const manifest = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
  const results = [];
  for (const fixture of manifest) {
    const bytes = fs.readFileSync(fixture.pcmPath);
    const pcm = Int16Array.from({ length: bytes.length / 2 }, (_, i) => bytes.readInt16LE(i * 2));
    const result = await analyzePcm(pcm, fixture.sampleRate);
    results.push({ id: fixture.id, parameters: result.parameters, coverage: result.coverage,
      pitchTrack: result.pitchTrack, formantTracks: result.formantTracks });
  }
  fs.writeFileSync(process.argv[3], JSON.stringify(results));
})().catch(error => { console.error(error); process.exitCode = 1; });
